import numpy as np,pandas as pd,glob
from scipy.optimize import least_squares
D={f:pd.read_csv(f) for f in glob.glob('train/*.csv')}
def sim(p,d,ds=10):
    kq,Tq,kp,Tw,Tp=p
    t=d.time_s.values[::ds];V=d.voltage_pu.values[::ds];th=d.bus_angle_rad.values[::ds];vs=d.voltage_setpoint_pu.values[::ds]
    dt=t[1]-t[0];P0=d.active_power_pu[0];Q0=d.reactive_power_pu[0];V0=V[0]
    q=Q0;xf=th[0];pp=P0;P=[];Q=[]
    for i in range(len(t)):
        q+=dt*(Q0+kq*(vs[i]-V[i])-q)/Tq
        xf+=dt*(th[i]-xf)/Tw
        pp+=dt*(P0-kp*(th[i]-xf)/Tw-pp)/Tp
        P.append(pp);Q.append(q)
    return np.array(P),np.array(Q)
def res(p):
    r=[]
    for f,d in D.items():
        if 'fault' in f: continue
        P,Q=sim(p,d);r+=[P-d.active_power_pu.values[::10],Q-d.reactive_power_pu.values[::10]]
    return np.concatenate(r)
s=least_squares(res,[5,.1,.5,.5,.1],bounds=([0,.01,0,.01,.01],[100,5,50,10,5]))
print(s.x,np.sqrt(np.mean(s.fun**2)),np.sqrt(np.mean(res([0,1,0,1,1])**2)))
